package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonIdentityInfo;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.annotation.SimpleObjectIdResolver;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.annotation.JsonIdentityInfo;
import com.fasterxml.jackson.databind.introspect.ObjectIdGenerator;
import com.fasterxml.jackson.databind.introspect.ObjectIdResolver;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObjectIdInfo_ObjectIdInfo_TriageGen0Test {

    // Mock implementations for testing purposes
    static class MockGenerator extends ObjectIdGenerator<Object> {
        @Override
        public Object generateObjectId(Object master) { return null; }
    }

    static class MockResolver implements ObjectIdResolver {
        @Override
        public Object resolveId(Object id) { return null; }
        @Override
        public ObjectIdGenerator<Object> getObjectIdGenerator() { return null; }
    }

    static class TestScope {}

    @Test
    public void testConstructorAndGetters() {
        PropertyName name = PropertyName.construct("id", false);
        Class<?> scope = TestScope.class;
        Class<? extends ObjectIdGenerator<?>> gen = MockGenerator.class;
        Class<? extends ObjectIdResolver> resolver = MockResolver.class;

        ObjectIdInfo info = new ObjectIdInfo(name, scope, gen, resolver);

        assertEquals(name, info.getPropertyName());
        assertEquals(scope, info.getScope());
        assertEquals(gen, info.getGeneratorType());
        assertEquals(resolver, info.getResolverType());
        assertFalse("Default alwaysAsId should be false", info.getAlwaysAsId());
    }

    @Test
    public void testWithAlwaysAsId() {
        PropertyName name = PropertyName.construct("id", false);
        Class<?> scope = TestScope.class;
        Class<? extends ObjectIdGenerator<?>> gen = MockGenerator.class;
        Class<? extends ObjectIdResolver> resolver = MockResolver.class;

        ObjectIdInfo info = new ObjectIdInfo(name, scope, gen, resolver);

        // Test changing state to true
        ObjectIdInfo infoTrue = info.withAlwaysAsId(true);
        assertTrue(infoTrue.getAlwaysAsId());
        assertEquals(name, infoTrue.getPropertyName());
        assertEquals(scope, infoTrue.getScope());
        assertEquals(gen, infoTrue.getGeneratorType());
        assertEquals(resolver, infoTrue.getResolverType());

        // Test changing state back to false
        ObjectIdInfo infoFalse = infoTrue.withAlwaysAsId(false);
        assertFalse(infoFalse.getAlwaysAsId());
    }

    @Test
    public void testToString() {
        PropertyName name = PropertyName.construct("id", false);
        Class<?> scope = TestScope.class;
        Class<? extends ObjectIdGenerator<?>> gen = MockGenerator.class;
        Class<? extends ObjectIdResolver> resolver = MockResolver.class;

        ObjectIdInfo info = new ObjectIdInfo(name, scope, gen, resolver);
        String toStringResult = info.toString();

        assertNotNull(toStringResult);
        assertTrue(toStringResult.contains("id"));
        assertTrue(toStringResult.contains("TestScope"));
    }
}
